/**
 * Arithmetic system functions: ADD, SUB, MUL, DIV, INTDIV, MOD, POW, POWPROD, NEG
 *
 * Uses ratmath core type methods for exact arithmetic.
 */

import { Integer, Rational } from "@ratmath/core";
import { formatValue } from "../format.js";
import { executeRangeOperation, rangeEvidence } from "../../runtime/range-arithmetic.js";
import {
    calculusGraphRangeValue,
    calculusGraphRangeCheckValue,
    calculusGraphRecognitionValue,
    calculusGraphSimplificationValue,
    calculusGraphSimplificationCheckValue,
    calculusGraphRewriteValue,
    calculusGraphRewriteCheckValue,
    calculusDerivativeCheckValue,
    calculusDerivativeSignValue,
    calculusLipschitzRangeValue,
    calculusTaylorRangeValue,
} from "../../runtime/calculus-range.js";
import {
    rationalBoxValue,
    multivariateRangeRequestValue,
    jacobianBoxRangeValue,
    affineBoxRangeValue,
    taylorModelBoxRangeValue,
    multivariateRangeCheckValue,
} from "../../runtime/multivariate-range.js";
import {
    RANGE_MATH_POLICY_KEY,
    mergeRangeMathPolicy,
    rangeMathPolicy,
} from "../../runtime/range-policy.js";

/**
 * Ensure a value is a ratmath numeric type.
 * Native numbers/BigInts get wrapped as Integer.
 */
function ensureNumeric(val) {
    if (val instanceof Integer || val instanceof Rational) return val;
    // Robust check for ratmath types across different instances of core
    if (val && typeof val === "object" && typeof val.add === "function" && typeof val.multiply === "function") return val;
    if (typeof val === "bigint") return new Integer(val);
    if (typeof val === "number") {
        if (Number.isInteger(val)) return new Integer(val);
        // Approximate: convert to rational
        const str = val.toString();
        const parts = str.split(".");
        if (parts.length === 2) {
            const den = 10n ** BigInt(parts[1].length);
            const num = BigInt(parts[0]) * den + BigInt(parts[1]);
            return new Rational(num, den);
        }
        return new Integer(BigInt(Math.floor(val)));
    }
    
    if (typeof val === "function" || (val && typeof val === "object" && (val.type === "lambda" || val.type === "function" || val.type === "sysref" || val.type === "partial" || val.type === "arityCap"))) {
        throw new Error("Cannot use function/lambda in arithmetic. If you intended to call a function, its name must be Capitalised.");
    }

    throw new Error(`Cannot use ${typeof val} in arithmetic`);
}

function stringify(val) {
    return formatValue(val);
}

function toQuotientParts(value) {
    if (value instanceof Integer) {
        return { numerator: value.value, denominator: 1n };
    }
    if (value instanceof Rational) {
        return { numerator: value.numerator, denominator: value.denominator };
    }
    return { numerator: BigInt(value.toString()), denominator: 1n };
}

function ceilDiv(numerator, denominator) {
    const q = numerator / denominator;
    const r = numerator % denominator;
    if (r === 0n) return q;
    return numerator >= 0n ? q + 1n : q;
}

function floorDiv(numerator, denominator) {
    const q = numerator / denominator;
    const r = numerator % denominator;
    if (r === 0n) return q;
    return numerator < 0n ? q - 1n : q;
}

function roundDiv(numerator, denominator) {
    const absNum = numerator < 0n ? -numerator : numerator;
    const floor = absNum / denominator;
    const remainder = absNum % denominator;
    const rounded = remainder * 2n >= denominator ? floor + 1n : floor;
    return numerator < 0n ? -rounded : rounded;
}

function requirePositiveDivisor(value, operation) {
    const { numerator } = toQuotientParts(value);
    if (numerator <= 0n) {
        throw new Error(`${operation} divisor must be positive`);
    }
}

function rationalModulo(dividend, divisor) {
    requirePositiveDivisor(divisor, "Modulo");
    const quotient = dividend.divide(divisor);
    const { numerator, denominator } = toQuotientParts(quotient);
    const floor = new Integer(floorDiv(numerator, denominator));
    const remainder = dividend.subtract(divisor.multiply(floor));
    if (remainder instanceof Rational && remainder.denominator === 1n) {
        return new Integer(remainder.numerator);
    }
    return remainder;
}

function requireNonNegativeInteger(value, operation) {
    const numeric = ensureNumeric(value);
    if (numeric instanceof Integer) {
        if (numeric.value < 0n) throw new Error(`${operation} is not defined for negative integers`);
        return numeric;
    }
    if (numeric instanceof Rational && numeric.denominator === 1n) {
        if (numeric.numerator < 0n) throw new Error(`${operation} is not defined for negative integers`);
        return new Integer(numeric.numerator);
    }
    throw new Error(`${operation} requires an integer`);
}

export const arithmeticFunctions = {
    RATIONAL_BOX: {
        impl(args) {
            if (args.length !== 1) throw new Error("RationalBox expects one bindings map");
            return rationalBoxValue(args[0]);
        },
        pure: true,
        doc: "Construct a checked Cartesian box of closed bounded rational intervals",
    },

    MULTIVARIATE_RANGE_REQUEST: {
        impl(args) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("MultivariateRangeRequest expects expression, box bindings, and optional options");
            }
            return multivariateRangeRequestValue(args[0], args[1], args[2]);
        },
        pure: true,
        doc: "Construct a portable multivariate range request",
    },

    JACOBIAN_BOX_RANGE: {
        impl(args, context) {
            if (args.length < 3 || args.length > 4) {
                throw new Error("JacobianBoxRange expects expression, gradient/Jacobian, box, and optional options");
            }
            return jacobianBoxRangeValue(args[0], args[1], args[2], args[3], context);
        },
        pure: true,
        doc: "Certify a scalar range on a rational box using checked Jacobian bounds",
    },

    AFFINE_BOX_RANGE: {
        impl(args, context) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("AffineBoxRange expects expression, box, and optional options");
            }
            return affineBoxRangeValue(args[0], args[1], args[2], context);
        },
        pure: true,
        doc: "Certify a rational-box range with correlation-preserving affine arithmetic",
    },

    TAYLOR_MODEL_BOX_RANGE: {
        impl(args, context) {
            if (args.length < 4 || args.length > 5) {
                throw new Error("TaylorModelBoxRange expects expression, gradient, Hessian, box, and optional options");
            }
            return taylorModelBoxRangeValue(
                args[0], args[1], args[2], args[3], args[4], context,
            );
        },
        pure: true,
        doc: "Certify a rational-box range with a multivariate Taylor model and Hessian remainder",
    },

    MULTIVARIATE_RANGE_CHECK: {
        impl(args) {
            if (args.length !== 1) throw new Error("MultivariateRangeCheck expects one result");
            return multivariateRangeCheckValue(args[0]);
        },
        pure: true,
        doc: "Independently recompute a Jacobian, affine, or Taylor-model enclosure",
    },

    CALCULUS_RANGE: {
        impl(args, context) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("CalculusRange expects an expression, bindings, and optional options");
            }
            return calculusGraphRangeValue(args[0], args[1], args[2], context);
        },
        pure: true,
        doc: "Evaluate a supported immutable Calculus graph over exact rational ranges",
    },

    CALCULUS_RANGE_CHECK: {
        impl(args) {
            if (args.length !== 1) throw new Error("CalculusRangeCheck expects one graph-range result");
            return calculusGraphRangeCheckValue(args[0]);
        },
        pure: true,
        doc: "Return the checker record attached to a Calculus graph-range result",
    },

    CALCULUS_RANGE_RECOGNIZE: {
        impl(args) {
            if (args.length !== 2) {
                throw new Error("CalculusRangeRecognize expects an expression and variable");
            }
            return calculusGraphRecognitionValue(args[0], args[1]);
        },
        pure: true,
        doc: "Recognize an exact polynomial or source-domain-preserving rational graph",
    },

    CALCULUS_GRAPH_SIMPLIFY: {
        impl(args) {
            if (args.length !== 1) {
                throw new Error("CalculusGraphSimplify expects one expression");
            }
            return calculusGraphSimplificationValue(args[0]);
        },
        pure: true,
        doc: "Apply and check the canonical domain-preserving Calculus graph simplifier",
    },

    CALCULUS_GRAPH_SIMPLIFICATION_CHECK: {
        impl(args) {
            if (args.length !== 1) {
                throw new Error("CalculusGraphSimplificationCheck expects one simplification record");
            }
            return calculusGraphSimplificationCheckValue(args[0]);
        },
        pure: true,
        doc: "Independently recompute a canonical Calculus graph simplification",
    },

    CALCULUS_GRAPH_REWRITE: {
        impl(args) {
            if (args.length !== 3) {
                throw new Error("CalculusGraphRewrite expects source, target, and theorem");
            }
            return calculusGraphRewriteValue(args[0], args[1], args[2]);
        },
        pure: true,
        doc: "Create and independently check a theorem-named Calculus graph rewrite",
    },

    CALCULUS_GRAPH_REWRITE_CHECK: {
        impl(args) {
            if (args.length !== 1) throw new Error("CalculusGraphRewriteCheck expects one rewrite record");
            return calculusGraphRewriteCheckValue(args[0]);
        },
        pure: true,
        doc: "Check a Calculus graph rewrite theorem and retained domain obligations",
    },

    CALCULUS_DERIVATIVE_CHECK: {
        impl(args) {
            if (args.length !== 1) {
                throw new Error("CalculusDerivativeCheck expects one transformation");
            }
            return calculusDerivativeCheckValue(args[0]);
        },
        pure: true,
        doc: "Independently recompute and check a primitive Calculus derivative transformation",
    },

    CALCULUS_DERIVATIVE_SIGN: {
        impl(args, context) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("CalculusDerivativeSign expects a transformation, bindings, and optional options");
            }
            return calculusDerivativeSignValue(args[0], args[1], args[2], context);
        },
        pure: true,
        doc: "Certify a uniform derivative sign for a checked primitive Calculus transformation",
    },

    CALCULUS_LIPSCHITZ_RANGE: {
        impl(args, context) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("CalculusLipschitzRange expects a derivative transformation, bindings, and optional options");
            }
            return calculusLipschitzRangeValue(args[0], args[1], args[2], context);
        },
        pure: true,
        doc: "Certify a range by midpoint values and bounded first derivatives",
    },

    CALCULUS_TAYLOR_RANGE: {
        impl(args, context) {
            if (args.length < 2 || args.length > 3) {
                throw new Error("CalculusTaylorRange expects a second-derivative transformation, bindings, and optional options");
            }
            return calculusTaylorRangeValue(args[0], args[1], args[2], context);
        },
        pure: true,
        doc: "Certify a first-order midpoint Taylor range with second-derivative remainder",
    },

    RANGE_POLICY: {
        lazy: true,
        impl(args, context, evaluate) {
            if (args.length !== 2) throw new Error("RangePolicy expects options and one expression");
            const options = evaluate(args[0]);
            const policy = mergeRangeMathPolicy(rangeMathPolicy(context), options);
            context.push(undefined);
            context.setScopedEnv(RANGE_MATH_POLICY_KEY, policy);
            try {
                return evaluate(args[1]);
            } finally {
                context.pop();
            }
        },
        pure: false,
        doc: "Evaluate an expression under an inherited range-domain policy",
    },

    RANGE_EVIDENCE: {
        impl(args) {
            return rangeEvidence(args[0]);
        },
        pure: true,
        doc: "Return the checked rangeEvidence metadata attached to a range result",
    },

    RANGE_ADD: {
        impl(args, context) { return executeRangeOperation("add", args, context); },
        pure: true,
        doc: "Exact Cartesian image of range-set addition",
    },
    RANGE_SUBTRACT: {
        impl(args, context) { return executeRangeOperation("subtract", args, context); },
        pure: true,
        doc: "Exact Cartesian image of range-set subtraction",
    },
    RANGE_MULTIPLY: {
        impl(args, context) { return executeRangeOperation("multiply", args, context); },
        pure: true,
        doc: "Exact Cartesian image of range-set multiplication",
    },
    RANGE_DIVIDE: {
        impl(args, context) { return executeRangeOperation("divide", args, context); },
        pure: true,
        doc: "Exact defined image of range-set division",
    },
    RANGE_NEGATE: {
        impl(args, context) { return executeRangeOperation("negate", args, context); },
        pure: true,
        doc: "Exact image of range-set negation",
    },
    RANGE_ABSOLUTE_VALUE: {
        impl(args, context) { return executeRangeOperation("absoluteValue", args, context); },
        pure: true,
        doc: "Exact image of range-set absolute value",
    },
    RANGE_RECIPROCAL: {
        impl(args, context) { return executeRangeOperation("reciprocal", args, context); },
        pure: true,
        doc: "Exact defined image of range-set reciprocal",
    },
    RANGE_INTEGER_POWER: {
        impl(args, context) { return executeRangeOperation("integerPower", args, context); },
        pure: true,
        doc: "Exact defined image of a range set raised to an integer power",
    },

    ADD: {
        impl(args) {
            if (args.length === 0) return new Integer(0n);
            if (args.length === 1) return args[0];

            // String concatenation support
            const isStr = (v) => typeof v === "string" || (v && typeof v === "object" && v.type === "string");
            const getStr = (v) => stringify(v);

            if (args.some(isStr)) {
                return { type: "string", value: args.map(getStr).join("") };
            }

            let result = ensureNumeric(args[0]);
            for (let i = 1; i < args.length; i++) {
                result = result.add(ensureNumeric(args[i]));
            }
            return result;
        },
        pure: true,
        doc: "Addition or string concatenation",
    },

    SUB: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            return a.subtract(b);
        },
        pure: true,
        doc: "Subtraction",
    },

    MUL: {
        impl(args) {
            if (args.length === 0) return new Integer(1n);
            if (args.length === 1) return ensureNumeric(args[0]);

            let result = ensureNumeric(args[0]);
            for (let i = 1; i < args.length; i++) {
                result = result.multiply(ensureNumeric(args[i]));
            }
            return result;
        },
        pure: true,
        doc: "Multiplication (Product of values)",
    },

    DIV: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            return a.divide(b);
        },
        pure: true,
        doc: "Division",
    },

    INTDIV: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            const quotient = a.divide(b);
            const { numerator, denominator } = toQuotientParts(quotient);
            return new Integer(floorDiv(numerator, denominator));
        },
        pure: true,
        doc: "Integer division (floor)",
    },

    DIVUP: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            const quotient = a.divide(b);
            const { numerator, denominator } = toQuotientParts(quotient);
            return new Integer(ceilDiv(numerator, denominator));
        },
        pure: true,
        doc: "Ceiling division",
    },

    DIVROUND: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            const quotient = a.divide(b);
            const { numerator, denominator } = toQuotientParts(quotient);
            return new Integer(roundDiv(numerator, denominator));
        },
        pure: true,
        doc: "Rounded division",
    },

    MOD: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            return rationalModulo(a, b);
        },
        pure: true,
        doc: "Floor modulo with a positive divisor",
    },

    DIVMOD: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            const b = ensureNumeric(args[1]);
            requirePositiveDivisor(b, "Division with remainder");
            const quotient = a.divide(b);
            const parts = toQuotientParts(quotient);
            const floor = new Integer(floorDiv(parts.numerator, parts.denominator));
            return {
                type: "tuple",
                values: [floor, rationalModulo(a, b)],
            };
        },
        pure: true,
        doc: "Floor quotient and exact remainder for a positive divisor",
    },

    POW: {
        impl(args) {
            const base = ensureNumeric(args[0]);
            const exp = ensureNumeric(args[1]);
            const expValue = exp instanceof Integer ? exp.value : Number(exp.toString());
            return base.pow(expValue);
        },
        pure: true,
        doc: "Exponentiation",
    },

    POWPROD: {
        impl(args) {
            const base = ensureNumeric(args[0]);
            const exp = ensureNumeric(args[1]);
            const expValue = exp instanceof Integer ? exp.value : Number(exp.toString());
            return base.pow(expValue);
        },
        pure: true,
        doc: "Exponentiation/product power (currently same implementation as POW)",
    },

    NEG: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            return a.negate();
        },
        pure: true,
        doc: "Negation",
    },

    FACTORIAL: {
        impl(args) {
            return requireNonNegativeInteger(args[0], "Factorial").factorial();
        },
        pure: true,
        doc: "Factorial of a non-negative integer",
    },

    DOUBLE_FACTORIAL: {
        impl(args) {
            return requireNonNegativeInteger(args[0], "Double factorial").doubleFactorial();
        },
        pure: true,
        doc: "Double factorial of a non-negative integer",
    },

    ABS: {
        impl(args) {
            const a = ensureNumeric(args[0]);
            return a instanceof Integer
                ? new Integer(a.value < 0n ? -a.value : a.value)
                : new Rational(a.numerator < 0n ? -a.numerator : a.numerator, a.denominator);
        },
        pure: true,
        doc: "Absolute value",
    },
};
